CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tenants (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, name VARCHAR(160) NOT NULL, slug VARCHAR(80) NOT NULL UNIQUE, database_name VARCHAR(120) NOT NULL UNIQUE, status ENUM('active','provisioning','suspended') NOT NULL DEFAULT 'provisioning', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS domains (id INT AUTO_INCREMENT PRIMARY KEY, tenant_id INT NOT NULL, hostname VARCHAR(255) NOT NULL UNIQUE, type ENUM('subdomain','custom') NOT NULL DEFAULT 'subdomain', status ENUM('pending','active','blocked') NOT NULL DEFAULT 'pending', verification_token VARCHAR(120) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX idx_domains_tenant ON domains(tenant_id);
CREATE INDEX idx_tenants_user ON tenants(user_id);
